//! Pins of SimGroup classes: `data/gf2/logic_schema.toml`.
//!
//! The file lists, for every class packet, the attributes that are messages
//! the object listens to (`in`), messages it sends (`out`), GUIDs of other
//! objects (`link`), resource references (`asset`) and named parameters, each
//! with how sure the research is (`exe`, `data`, `guess`). It is generated by
//! `research/logic_schema.py`; see `docs/logic-graph.md` §2.

use std::collections::HashMap;
use std::sync::OnceLock;

use serde::Deserialize;

use crate::game_types::SemanticType;
use crate::hash::sdbm;
use crate::resource::simgroup::{Kind, Object, SimGroup};
use crate::{Error, Result};

static GF2_SCHEMA: &str = include_str!("../../../../data/gf2/logic_schema.toml");
static GF2_ENGINE: &str = include_str!("../../../../data/gf2/engine_messages.txt");

/// What an attribute is in the graph.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Deserialize, serde::Serialize)]
#[serde(rename_all = "lowercase")]
pub enum PinKind {
    /// A message the object listens to.
    In,
    /// A message the object sends.
    Out,
    /// The GUID of another SimGroup object.
    Link,
    /// A resource reference.
    Asset,
    /// Any other value.
    Param,
}

/// How a fact of the schema is known.
#[derive(
    Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord, Deserialize, serde::Serialize,
)]
#[serde(rename_all = "lowercase")]
pub enum Confidence {
    /// Guessed from names and patterns.
    Guess,
    /// Inferred from the game files.
    Data,
    /// Seen in the code of `godfather2.exe`.
    Exe,
}

/// Category of an object class, for colours and grouping.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Deserialize, serde::Serialize)]
#[serde(rename_all = "lowercase")]
pub enum Category {
    Trigger,
    Logic,
    Ui,
    Audio,
    Spawn,
    Job,
    Cinematic,
    Relay,
    /// Logic object without a position.
    Action,
    /// Object placed in the world.
    Object,
    /// Not an object class (the engine, a script).
    Other,
}

impl Category {
    pub fn name(self) -> &'static str {
        match self {
            Self::Trigger => "trigger",
            Self::Logic => "logic",
            Self::Ui => "ui",
            Self::Audio => "audio",
            Self::Spawn => "spawn",
            Self::Job => "job",
            Self::Cinematic => "cinematic",
            Self::Relay => "relay",
            Self::Action => "action",
            Self::Object => "object",
            Self::Other => "other",
        }
    }
}

/// One attribute of a class packet.
#[derive(Debug, Clone, PartialEq)]
pub struct AttrPin {
    pub index: u16,
    pub pin: PinKind,
    /// How the pin kind is known; `None` for parameters.
    pub conf: Option<Confidence>,
    pub name: Option<String>,
    pub name_conf: Option<Confidence>,
    /// Index of the attribute that holds the delay of an `out` pin.
    pub delay: Option<u16>,
    pub kind: Option<Kind>,
}

#[derive(Deserialize)]
struct FileAttr {
    i: u16,
    pin: PinKind,
    conf: Option<Confidence>,
    name: Option<String>,
    name_conf: Option<Confidence>,
    delay: Option<u16>,
    kind: Option<String>,
}

#[derive(Deserialize)]
struct FilePacket {
    hash: String,
    attrs: Vec<FileAttr>,
}

#[derive(Deserialize)]
struct File {
    class: HashMap<String, Category>,
    layout: HashMap<String, Vec<String>>,
    packet: HashMap<String, FilePacket>,
}

/// The pins of all classes.
#[derive(Debug, Default)]
pub struct LogicSchema {
    /// Packet class hash → attributes, by index.
    packets: HashMap<u32, Vec<AttrPin>>,
    categories: HashMap<u32, Category>,
    /// Object class hash → packets of a new object: class hash, attribute count.
    layouts: HashMap<u32, Vec<(u32, u16)>>,
    names: HashMap<u32, String>,
    engine: HashMap<u32, String>,
}

/// Hash of a class named in the schema: unnamed classes are written as
/// their hash (eight hexadecimal digits).
fn class_hash(name: &str) -> u32 {
    match u32::from_str_radix(name, 16) {
        Ok(h) if name.len() == 8 => h,
        _ => sdbm(name.to_ascii_lowercase().as_bytes()),
    }
}

/// An attribute of a packet with its meaning ([`LogicSchema::typed_attrs`]).
#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize)]
pub struct TypedAttr {
    pub index: u16,
    pub name: Option<String>,
    #[serde(rename = "type")]
    pub ty: SemanticType,
    pub conf: Confidence,
    /// Values of the game files that fit the type, and all values seen.
    pub seen: Option<(u32, u32)>,
    /// Where a hand-read type comes from.
    pub source: Option<&'static str>,
}

impl LogicSchema {
    /// Parses the TOML schema and the list of engine messages (one name per
    /// line, `#` comments).
    pub fn parse(toml_text: &str, engine: &str) -> Result<Self> {
        let file: File = toml::from_str(toml_text)
            .map_err(|e| Error::InvalidArgument(format!("logic schema: {e}")))?;
        let mut schema = Self::default();
        for (name, cat) in file.class {
            let h = class_hash(&name);
            schema.categories.insert(h, cat);
            schema.names.insert(h, name);
        }
        for (name, packets) in file.layout {
            let h = class_hash(&name);
            let mut layout = Vec::new();
            for p in packets {
                let (c, n) = p.split_once(':').ok_or_else(|| {
                    Error::InvalidArgument(format!("logic schema: bad layout entry {p}"))
                })?;
                let c = u32::from_str_radix(c, 16)
                    .map_err(|_| Error::InvalidArgument(format!("logic schema: bad hash {c}")))?;
                let n = n
                    .parse()
                    .map_err(|_| Error::InvalidArgument(format!("logic schema: bad count {n}")))?;
                layout.push((c, n));
            }
            schema.layouts.insert(h, layout);
        }
        for (name, packet) in file.packet {
            let h = u32::from_str_radix(&packet.hash, 16).map_err(|_| {
                Error::InvalidArgument(format!("logic schema: bad hash {}", packet.hash))
            })?;
            schema.names.entry(h).or_insert(name);
            let mut attrs: Vec<AttrPin> = packet
                .attrs
                .into_iter()
                .map(|a| AttrPin {
                    index: a.i,
                    pin: a.pin,
                    conf: a.conf,
                    name: a.name,
                    name_conf: a.name_conf,
                    delay: a.delay,
                    kind: a.kind.as_deref().and_then(kind_from_name),
                })
                .collect();
            attrs.sort_by_key(|a| a.index);
            schema.packets.insert(h, attrs);
        }
        for line in engine.lines() {
            let line = line.trim();
            if !line.is_empty() && !line.starts_with('#') {
                schema
                    .engine
                    .insert(crate::hash::string_id(line), line.to_owned());
            }
        }
        Ok(schema)
    }

    /// The schema of The Godfather II (PC): the classes of the engine and
    /// the classes of native mods named by `DOCTOR_TOOLKIT_CLASSES`
    /// (`game_types::custom`).
    pub fn gf2() -> &'static Self {
        static SCHEMA: OnceLock<LogicSchema> = OnceLock::new();
        SCHEMA.get_or_init(|| {
            let mut schema = Self::engine();
            schema.add_custom(crate::game_types::custom::installed());
            schema
        })
    }

    /// The classes of the engine only.
    pub fn engine() -> Self {
        Self::parse(GF2_SCHEMA, GF2_ENGINE).expect("valid built-in schema")
    }

    /// Adds classes of native mods (checked by `game_types::custom::parse`):
    /// their names, categories, packets and the layout of a new object.
    pub fn add_custom(&mut self, classes: &[crate::game_types::custom::CustomClass]) {
        for class in classes {
            let layout = class.layout(self);
            self.names.insert(class.hash, class.name.clone());
            self.categories.insert(class.hash, class.category);
            self.layouts.insert(class.hash, layout);
            self.packets.insert(class.hash, class.pins());
        }
    }

    /// Attributes of a class packet that the schema knows.
    pub fn packet(&self, class: u32) -> &[AttrPin] {
        self.packets.get(&class).map_or(&[], Vec::as_slice)
    }

    /// Hashes of the classes whose packet the schema describes, sorted.
    pub fn packet_classes(&self) -> Vec<u32> {
        let mut out: Vec<u32> = self.packets.keys().copied().collect();
        out.sort_unstable();
        out
    }

    /// One attribute of a class packet.
    pub fn attr(&self, class: u32, index: u16) -> Option<&AttrPin> {
        self.packet(class).iter().find(|a| a.index == index)
    }

    pub fn category(&self, class: u32) -> Category {
        self.categories
            .get(&class)
            .copied()
            .unwrap_or(Category::Other)
    }

    /// Packets of a new object of `class`: class hash and attribute count,
    /// base class first.
    pub fn layout(&self, class: u32) -> Option<&[(u32, u16)]> {
        self.layouts.get(&class).map(Vec::as_slice)
    }

    /// Name of a class as the schema spells it.
    pub fn class_name(&self, class: u32) -> Option<&str> {
        self.names.get(&class).map(String::as_str)
    }

    /// Object classes the schema knows, by name.
    pub fn classes(&self) -> Vec<(u32, &str, Category)> {
        let mut out: Vec<_> = self
            .categories
            .iter()
            .map(|(&h, &c)| (h, self.names.get(&h).map_or("", String::as_str), c))
            .collect();
        out.sort_by(|a, b| a.1.cmp(b.1));
        out
    }

    /// Whether a message (by hash) is one the engine itself sends or listens to.
    pub fn engine_message(&self, hash: u32) -> Option<&str> {
        self.engine.get(&hash).map(String::as_str)
    }

    /// What the value of an attribute means, and how that is known: a
    /// message heard or sent for `in` and `out` pins, otherwise the type of
    /// `data/gf2/attr_types.toml` (a reference to an object of a class, a
    /// resource of a type, a value of a list, seconds, money, a flag).
    pub fn semantic(&self, class: u32, index: u16) -> Option<(SemanticType, Confidence)> {
        match self.attr(class, index) {
            Some(a) if a.pin == PinKind::In => {
                Some((SemanticType::MsgIn, a.conf.unwrap_or(Confidence::Guess)))
            }
            Some(a) if a.pin == PinKind::Out => {
                Some((SemanticType::MsgOut, a.conf.unwrap_or(Confidence::Guess)))
            }
            _ => crate::game_types::attr_type(class, index).map(|t| (t.ty, t.conf)),
        }
    }

    /// Every attribute of the packet of `class` whose meaning is known
    /// (message pins and the typed attributes), by index.
    pub fn typed_attrs(&self, class: u32) -> Vec<TypedAttr> {
        let mut indexes: Vec<u16> = self.packet(class).iter().map(|a| a.index).collect();
        indexes.extend(
            crate::game_types::attr_types()
                .iter()
                .filter(|r| r.0 == class)
                .map(|r| r.1),
        );
        indexes.sort_unstable();
        indexes.dedup();
        indexes
            .into_iter()
            .filter_map(|index| {
                let (ty, conf) = self.semantic(class, index)?;
                let extra = crate::game_types::attr_type(class, index);
                Some(TypedAttr {
                    index,
                    name: self.attr(class, index).and_then(|a| a.name.clone()),
                    ty,
                    conf,
                    seen: extra.map(|e| e.seen),
                    source: extra.map(|e| e.source).filter(|s| !s.is_empty()),
                })
            })
            .collect()
    }

    /// Pins of an object: every schema attribute of its packets that is not
    /// a plain parameter, plus named parameters, in packet order.
    pub fn object_pins(&self, group: &SimGroup, object: &Object) -> Vec<ObjectPin> {
        let mut out = Vec::new();
        for (slot, packet) in group.object_packets(object).enumerate() {
            for a in self.packet(packet.class.0) {
                let value = packet
                    .attrs
                    .iter()
                    .find(|v| v.index == a.index)
                    .map(|v| &v.value);
                out.push(ObjectPin {
                    slot,
                    class: packet.class.0,
                    attr: a.clone(),
                    value: value.cloned(),
                });
            }
        }
        out
    }

    /// Statistics: (packets, attributes by pin kind and confidence).
    pub fn coverage(&self) -> SchemaCoverage {
        let mut c = SchemaCoverage {
            classes: self.categories.len(),
            packets: self.packets.len(),
            ..SchemaCoverage::default()
        };
        for attrs in self.packets.values() {
            for a in attrs {
                let row = match a.pin {
                    PinKind::In => &mut c.inputs,
                    PinKind::Out => &mut c.outputs,
                    PinKind::Link => &mut c.links,
                    PinKind::Asset => &mut c.assets,
                    PinKind::Param => &mut c.params,
                };
                match a.conf {
                    Some(Confidence::Exe) => row[0] += 1,
                    Some(Confidence::Data) => row[1] += 1,
                    _ => row[2] += 1,
                }
                if a.name.is_some() {
                    c.named += 1;
                }
            }
        }
        c
    }
}

/// How much the schema covers: counts by confidence `[exe, data, other]`.
#[derive(Debug, Clone, Default, PartialEq, serde::Serialize)]
pub struct SchemaCoverage {
    pub classes: usize,
    pub packets: usize,
    pub inputs: [usize; 3],
    pub outputs: [usize; 3],
    pub links: [usize; 3],
    pub assets: [usize; 3],
    pub params: [usize; 3],
    pub named: usize,
}

/// A schema attribute of one object with its current value.
#[derive(Debug, Clone, PartialEq)]
pub struct ObjectPin {
    /// Slot of the packet in the object (`Object::packets[slot]`).
    pub slot: usize,
    /// Class of the packet.
    pub class: u32,
    pub attr: AttrPin,
    /// The stored value; `None` when the attribute is the default.
    pub value: Option<crate::resource::simgroup::Value>,
}

fn kind_from_name(name: &str) -> Option<Kind> {
    Some(match name {
        "int" => Kind::Int,
        "float" => Kind::Float,
        "hash" => Kind::Hash,
        "string" => Kind::String,
        "guid" => Kind::Guid,
        "vec3" => Kind::Vec3,
        "matrix" => Kind::Matrix,
        _ => return None,
    })
}
